@strawberry.type
class Query:
    @strawberry.field
    async def webhook_delivery_record(self, info: Info, delivery_id: uuid.UUID) -> Optional[WebhookLogType]:
        user = info.context.get("current_user")
        if not user:
            raise HTTPException(status_code=401, detail="Authentication required")

        loader: DataLoader = info.context["webhook_log_loader"]
        log_entry = await loader.load(delivery_id)
        if not log_entry:
            return None

        if log_entry.organization_id != user.organization_id:
            raise HTTPException(status_code=403, detail="Forbidden: access to webhook logs of other organizations denied")

        return WebhookLogType(
            id=log_entry.id,
            target_url=log_entry.endpoint_url,
            request_body=log_entry.payload_json,
            response_code=log_entry.http_status,
            hmac_signature=log_entry.signature_header
        )
